const inputData = $input.all();
const apolloResponse = inputData[0].json;

console.log('🔍 EXTRACT COMPANIES - Processing Apollo Response');

// Extract breadcrumbs for keywords
const breadcrumbs = apolloResponse.breadcrumbs || [];
const keywords = breadcrumbs
  .filter(b => b.signal_field_name === 'q_organization_keyword_tags')
  .map(b => b.value)
  .join(', ');

console.log('📋 Keywords:', keywords || 'NONE');
console.log('📊 Pagination:', apolloResponse.pagination);

// MERGE BOTH accounts AND organizations arrays
const accounts = apolloResponse.accounts || [];
const organizations = apolloResponse.organizations || [];
const companies = [...accounts, ...organizations];

console.log('✅ Found', accounts.length, 'accounts +', organizations.length, 'organizations =', companies.length, 'total companies');

if (companies.length === 0) {
  console.log('⚠️  NO COMPANIES FOUND - Check your Apollo search filters');
  return [];
}

// Process ALL companies
return companies.map((company, index) => {
  const org = company.organization || company;

  // Basic info
  const companyId = org.id || company.id;
  const companyName = org.name || company.name || 'Unknown';

  // Clean domain
  let companyDomain = org.primary_domain || org.website_url || org.domain || '';
  if (companyDomain) {
    companyDomain = companyDomain
      .replace(/^https?:\/\//, '')
      .replace(/^www\./, '')
      .replace(/\/$/, '')
      .trim();
  }

  // Location
  const companyLocation = org.country || org.city || company.country || 'Unknown';

  // Industry
  const companyIndustry = org.industry || org.primary_industry || company.industry || 'Technology';

  // Description
  const companyDescription = org.short_description || org.description || company.short_description || `${companyName} is a company`;

  // Employee count
  let employeeCount = null;
  const empSources = [org.estimated_num_employees, org.employee_count, company.estimated_num_employees];
  for (let emp of empSources) {
    if (emp) {
      if (typeof emp === 'string') {
        const match = emp.match(/(\d+)/);
        if (match) {
          employeeCount = parseInt(match[1]);
          break;
        }
      } else if (typeof emp === 'number') {
        employeeCount = parseInt(emp);
        break;
      }
    }
  }

  // Technologies
  let techArray = [];
  if (Array.isArray(org.technologies)) {
    techArray = org.technologies.map(t => typeof t === 'string' ? t : t?.name).filter(Boolean);
  }
  const techString = techArray.join(', ');

  if (index < 3) {
    console.log('\n🏢 Company', index + 1, ':', companyName);
    console.log('   Domain:', companyDomain || 'N/A');
    console.log('   Location:', companyLocation);
  }

  return {
    json: {
      company_id: companyId,
      company_name: companyName,
      company_domain: companyDomain,
      company_employees: employeeCount,
      company_location: companyLocation,
      company_industry: companyIndustry,
      company_technologies: techString,
      company_keywords: keywords,
      company_description: companyDescription
    }
  };
});

console.log('\n✅ Extracted all', companies.length, 'companies successfully');

const item = $input.item.json;

// Get the AI response from the LLM
let aiResponse = item.text || item.output || '';
aiResponse = aiResponse.replace(/```json\n?|\n?```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch (e) {
  console.log('❌ Failed to parse AI response');
  console.log('Raw response:', aiResponse);
  parsed = { 
    approved: false, 
    reason: 'AI response parsing failed',
    matched_keywords: [],
