  };
}

// Get the ORIGINAL company data
const originalCompanyData = $('Format Company Data').item.json;

// Extract matched keywords and technologies from AI response
const matchedKeywords = parsed.matched_keywords || [];
const matchedTechnologies = parsed.matched_technologies || [];

// Convert arrays to comma-separated strings
const keywordsString = matchedKeywords.join(', ');
const technologiesString = matchedTechnologies.join(', ');

console.log('🆔 Company ID:', originalCompanyData.company_id);
console.log('🏢 Company Name:', originalCompanyData.company_name);
console.log('🎯 AI Decision:', parsed.approved ? 'APPROVED' : 'REJECTED');
console.log('🏷️ Matched Keywords:', keywordsString || 'NONE');
console.log('🔧 Matched Technologies:', technologiesString || 'NONE');
