    company_name: originalCompanyData.company_name,
    company_domain: originalCompanyData.company_domain,
    company_employees: originalCompanyData.company_employees,
    company_location: originalCompanyData.company_location,
    company_industry: originalCompanyData.company_industry,
    company_description: originalCompanyData.company_description,

    // ✅ FILTERED: Only matched technologies and keywords (as strings)
    company_technologies: technologiesString,
    company_keywords: keywordsString,

    // Add AI validation
    company_approved: parsed.approved,
    company_validation_reason: parsed.reason,

    // Debug fields (optional - remove if not needed)
    _debug_matched_keywords_array: matchedKeywords,
    _debug_matched_technologies_array: matchedTechnologies
  }
};

// ============================================
// EXTRACT PEOPLE - PROPERLY FIXED FOR LOOPS
// Place this AFTER "Apollo People Search"
// ============================================

// Get Apollo response for current loop iteration
const apolloResponse = $input.item.json;
const people = apolloResponse.people || [];

// CRITICAL FIX: Get company data differently when in a loop
// Option 1: Get from Apollo response itself (nested in people)
// Option 2: Pass company data through the loop

// For now, get company from the first person's organization
// (All people are from same company in this search)
const org = people.length > 0 ? (people[0].organization || {}) : {};

// Try to get company data from previous node
let companyData = {};
try {
  // Try to get from Loop Over Items input
  const loopItems = $('Loop Over Items').item.json;
  if (loopItems) {
    companyData = loopItems;
  }
} catch (e) {
  console.log('⚠️ Could not get company from Loop Over Items');
}

// Fallback: use organization data from Apollo
if (!companyData.company_name && org.name) {
  companyData = {
    company_id: org.id,
    company_name: org.name,
    company_domain: org.primary_domain,
    company_employees: org.estimated_num_employees,
    company_location: org.country,
    company_industry: org.industry,
    company_technologies: '',
    company_keywords: '',
    company_description: org.short_description || ''
  };
}

console.log('✅ Processing people for company:', companyData.company_name || org.name);
console.log('👥 Total people found:', people.length);

if (people.length === 0) {
  console.log('⚠️ No people found for this company!');
  return [];
}

return people.map((person, index) => {
  // Organization data nested in person response
  const personOrg = person.organization || {};

  // Debug first person
  if (index === 0) {
    console.log('\n🔍 FIRST PERSON FULL DATA:');
    console.log('Name:', person.name);
    console.log('Title:', person.title);
    console.log('Seniority:', person.seniority);
    console.log('Departments:', person.departments);
    console.log('Subdepartments:', person.subdepartments);
  }

  // Extract person name
  let fullName = person.name || null;
  if (!fullName) {
    const firstName = person.first_name || '';
    const lastName = person.last_name || person.last_name_obfuscated || '';
    fullName = `${firstName} ${lastName}`.trim();
  }

  // Extract email
  const email = person.email || null;
  const hasEmail = person.has_email || false;

  // Extract title and seniority
  const title = person.title || '';
  const seniority = person.seniority || '';

  // Extract departments
  let departments = '';
  let departmentsArray = [];

  if (Array.isArray(person.departments) && person.departments.length > 0) {
    departmentsArray = person.departments;
    departments = person.departments.join(', ');
  } else if (Array.isArray(person.functions) && person.functions.length > 0) {
    departmentsArray = person.functions;
    departments = person.functions.join(', ');
  }

  // Extract subdepartments
  let subdepartments = '';
  let subdepartmentsArray = [];

  if (Array.isArray(person.subdepartments) && person.subdepartments.length > 0) {
    subdepartmentsArray = person.subdepartments;
    subdepartments = person.subdepartments.join(', ');
  }

  // Extract person location
  const personLocation = person.city && person.state && person.country
    ? `${person.city}, ${person.state}, ${person.country}`
    : person.city && person.country
    ? `${person.city}, ${person.country}`
    : person.state && person.country
    ? `${person.state}, ${person.country}`
    : person.country || '';

  // Extract LinkedIn URL
  const linkedinUrl = person.linkedin_url || null;

  // Log first 3 people
  if (index < 3) {
    console.log(`\n👤 Person ${index + 1}: ${fullName}`);
    console.log(`   Title: ${title}`);
    console.log(`   Seniority: ${seniority}`);
    console.log(`   Departments: ${departments}`);
    console.log(`   Subdepartments: ${subdepartments}`);
    console.log(`   Location: ${personLocation}`);
    console.log(`   Company: ${companyData.company_name || personOrg.name}`);
  }

  // Return person + company data
  return {
    json: {
      // Person data
      person_id: person.id,
      person_name: fullName,
      person_first_name: person.first_name,
      person_last_name: person.last_name || person.last_name_obfuscated,
      person_location: personLocation,
      person_title: title,
      person_seniority: seniority,

      // Department fields
      person_departments: departments,
      person_departments_array: departmentsArray,
      person_subdepartments: subdepartments,
      person_subdepartments_array: subdepartmentsArray,
      person_functions: person.functions || [],

      person_email: email,
      person_has_email: hasEmail,
      person_linkedin_url: linkedinUrl,

      // Company data - prefer passed data, fallback to Apollo org
      company_id: companyData.company_id || personOrg.id,
      company_name: companyData.company_name || personOrg.name,
      company_domain: companyData.company_domain || personOrg.primary_domain,
      company_employees: companyData.company_employees || personOrg.estimated_num_employees,
      company_location: companyData.company_location || personOrg.country,
      company_industry: companyData.company_industry || personOrg.industry,
      company_technologies: companyData.company_technologies || '',
      company_keywords: companyData.company_keywords || '',
      company_description: companyData.company_description || personOrg.short_description || ''
    }
  };
});

console.log(`\n✅ Extracted ${people.length} people with all data`);

// ============================================
// PARSE PERSONA VALIDATION - WITH SUBDEPARTMENTS
// ============================================

const item = $input.item.json;

// Get the AI response from the LLM
let aiResponse = item.text || item.output || '';
aiResponse = aiResponse.replace(/```json\n?|\n?```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch (e) {
