console.log('👤 Person ID from original:', originalPersonData.person_id);
console.log('📛 Person Name:', originalPersonData.person_name);
console.log('🎯 Persona Decision:', parsed.approved ? 'APPROVED' : 'REJECTED');
console.log('🏢 Departments:', originalPersonData.person_departments);
console.log('📂 Subdepartments:', originalPersonData.person_subdepartments);
console.log('⭐ Seniority:', originalPersonData.person_seniority);

return {
  json: {
    // Person data from Extract People
