    person_name: originalPersonData.person_name,
    person_first_name: originalPersonData.person_first_name,
    person_last_name: originalPersonData.person_last_name,
    person_title: originalPersonData.person_title,
    person_seniority: originalPersonData.person_seniority,

    // ✅ DEPARTMENTS - ALL FIELDS
    person_departments: originalPersonData.person_departments,
    person_departments_array: originalPersonData.person_departments_array,
    person_subdepartments: originalPersonData.person_subdepartments,           // ✅ ADDED
    person_subdepartments_array: originalPersonData.person_subdepartments_array, // ✅ ADDED
    person_functions: originalPersonData.person_functions,                      // ✅ ADDED

    person_email: originalPersonData.person_email,
    person_has_email: originalPersonData.person_has_email,
    person_linkedin_url: originalPersonData.person_linkedin_url,

    // Company data from Extract People
    company_id: originalPersonData.company_id,
    company_name: originalPersonData.company_name,
    company_domain: originalPersonData.company_domain,
    company_employees: originalPersonData.company_employees,
    company_location: originalPersonData.company_location,
    company_industry: originalPersonData.company_industry,
    company_technologies: originalPersonData.company_technologies,
    company_keywords: originalPersonData.company_keywords,
    company_description: originalPersonData.company_description,

    // Validation results
    persona_approved: parsed.approved,
    persona_validation_reason: parsed.reason
  }
};

// ============================================
// FORMAT FINAL DATA - PROPER VERSION
// ============================================

// Get Apollo enrichment response
const apolloResponse = $input.item.json;
const person = apolloResponse.person || {};
const org = person.organization || {};

// Extract email and CLEAN IT
let email = person.email || '';
email = email.replace(/"/g, '').replace(/'/g, '').trim();

const phone = person.phone_numbers?.[0]?.sanitized_number || person.mobile_phone || '';

// Extract departments
let departments = '';
if (Array.isArray(person.departments)) {
  departments = person.departments.join(', ');
} else if (Array.isArray(person.functions)) {
  departments = person.functions.join(', ');
}

// Extract subdepartments
let subdepartments = '';
if (Array.isArray(person.subdepartments)) {
  subdepartments = person.subdepartments.join(', ');
}

// Extract person location
const personLocation = person.city && person.state && person.country
  ? `${person.city}, ${person.state}, ${person.country}`
  : person.city && person.country
  ? `${person.city}, ${person.country}`
  : person.state && person.country
  ? `${person.state}, ${person.country}`
  : person.country || '';

console.log('📄 FORMAT FINAL DATA - Processing:', person.name);
console.log('🏢 Company from Apollo:', org.name);
console.log('🆔 Company ID from Apollo:', org.id);
console.log('📍 Person Location:', personLocation);
console.log('📂 Subdepartments:', subdepartments);

// ============================================
// Get PERSONA validation
// ============================================
const allPersonaData = $('Parse Persona Validation').all();
const personaData = allPersonaData.find(item => item.json.person_id === person.id);
const persona = personaData ? personaData.json : {};

console.log('👤 Persona Approved:', persona.persona_approved);

// ============================================
// Get COMPANY validation - SIMPLIFIED MATCHING
// ============================================
const allCompanyData = $('Parse Company Validation').all();

console.log('\n🔍 COMPANY MATCHING DEBUG:');
console.log('Total companies in Parse Company Validation:', allCompanyData.length);
console.log('Looking for company ID:', org.id);

// Simple ID-based matching (most reliable)
let companyData = allCompanyData.find(item => {
  const match = String(item.json.company_id) === String(org.id);
  if (match) {
    console.log('✅ MATCH FOUND by ID:', item.json.company_name);
  }
  return match;
});

// If no ID match, try domain matching
if (!companyData) {
  const orgDomain = (org.primary_domain || org.domain || '').toLowerCase().trim();
  console.log('⚠️ No ID match, trying domain:', orgDomain);

  companyData = allCompanyData.find(item => {
    const itemDomain = (item.json.company_domain || '').toLowerCase().trim();
    const match = orgDomain && itemDomain && orgDomain === itemDomain;
    if (match) {
      console.log('✅ MATCH FOUND by domain:', item.json.company_name);
    }
    return match;
  });
}

// If still no match, try name matching
if (!companyData) {
  const orgName = (org.name || '').toLowerCase().trim();
  console.log('⚠️ No domain match, trying name:', orgName);

  companyData = allCompanyData.find(item => {
    const itemName = (item.json.company_name || '').toLowerCase().trim();
    const match = orgName && itemName && orgName === itemName;
    if (match) {
      console.log('✅ MATCH FOUND by name:', item.json.company_name);
    }
    return match;
  });
}

const company = companyData ? companyData.json : {};

if (!companyData) {
  console.log('❌ ERROR: NO COMPANY MATCH FOUND!');
  console.log('Available company IDs:', allCompanyData.map(c => c.json.company_id).join(', '));
  console.log('Available company names:', allCompanyData.map(c => c.json.company_name).join(', '));
} else {
  console.log('\n✅ COMPANY DATA RETRIEVED:');
  console.log('   Name:', company.company_name);
  console.log('   ID:', company.company_id);
  console.log('   Domain:', company.company_domain);
  console.log('   🔧 Technologies:', company.company_technologies || 'EMPTY STRING');
  console.log('   🏷️ Keywords:', company.company_keywords || 'EMPTY STRING');
  console.log('   ✅ Approved:', company.company_approved);
}

// ============================================
// RETURN COMPLETE DATA
// ============================================
return {
  json: {
    // Person data
    person_id: person.id,
    person_name: person.name || `${person.first_name} ${person.last_name}`.trim(),
    person_first_name: person.first_name,
    person_last_name: person.last_name,
    person_title: person.title,
    person_seniority: person.seniority,
    person_location: personLocation,
    person_departments: departments,
    person_subdepartments: subdepartments,
    person_linkedin_url: person.linkedin_url,
    email: email,
    person_phone: phone,

    // Company data - ALL from Parse Company Validation
    company_id: company.company_id || org.id,
    company_name: company.company_name || org.name,
    company_domain: company.company_domain || org.primary_domain,
    company_location: company.company_location || org.country,
    company_employees: company.company_employees || org.estimated_num_employees,
    company_industry: company.company_industry || org.industry,
    company_description: company.company_description || org.short_description || '',

    // ✅ CRITICAL: Technologies and keywords from Parse Company Validation
    company_technologies: company.company_technologies || '',
    company_keywords: company.company_keywords || '',

    // Approval statuses
    company_approved: company.company_approved !== undefined ? company.company_approved : true,
    company_validation_reason: company.company_validation_reason || 'Approved',
    persona_approved: persona.persona_approved !== undefined ? persona.persona_approved : true,
    persona_validation_reason: persona.persona_validation_reason || 'Approved'
  }
};

// Extract ICP Node - PROPERLY HANDLING TECHNOLOGIES
// Technologies need to be intelligently parsed and converted to snake_case

const formData = $input.all()[0].json;

// ===== COMPANY FILTERS =====

// Parse company locations (comma or newline separated) and convert to lowercase
const companyLocations = formData['Company Locations']
  .split(/[,\n]/)
  .map(loc => loc.trim().toLowerCase())
  .filter(loc => loc.length > 0);

// Parse employee ranges and format as "min,max" for Apollo
const companyEmployees = formData['Employee Ranges'].map(range => {
  // Convert "51-100" to "51,100" format
  return range.replace('-', ',');
});

// Parse company keywords (newline separated) and convert to lowercase
const companyKeywords = formData['Company Keywords']
  .split(/\n/)
  .map(keyword => keyword.trim().toLowerCase())
  .filter(keyword => keyword.length > 0);

// Parse industries (newline separated) and convert to lowercase
const companyIndustries = formData['Industries']
  .split(/\n/)
  .map(industry => industry.trim().toLowerCase())
  .filter(industry => industry.length > 0);

// Parse technologies - Convert to snake_case format
// Input: "Amazon AWS Google Cloud Hosting Microsoft Azure REST APIs GraphQL Headless CMS Microservices Docker"
// Output: ["amazon_aws", "google_cloud_hosting", "microsoft_azure", "rest_apis", "graphql", "headless_cms", "microservices", "docker"]

// Known multi-word technologies mapping
const techMapping = {
  'amazon aws': 'amazon_aws',
  'google cloud hosting': 'google_cloud_hosting',
  'microsoft azure': 'microsoft_azure',
  'rest apis': 'rest_apis',
  'headless cms': 'headless_cms',
};

const techString = formData['Technologies'].toLowerCase();
const companyTechnologies = [];

// First, try to match multi-word technologies
let remainingTech = techString;
Object.keys(techMapping).forEach(multiWord => {
  if (remainingTech.includes(multiWord)) {
    companyTechnologies.push(techMapping[multiWord]);
    remainingTech = remainingTech.replace(multiWord, '');
  }
});

// Then add single-word technologies
const singleWords = remainingTech.split(/\s+/).filter(w => w.length > 0);
singleWords.forEach(word => {
  if (word.trim().length > 0) {
    companyTechnologies.push(word.trim());
  }
});

// ===== PERSON FILTERS =====

// Parse job titles (newline separated) - these are management levels
const jobTitles = formData['Job Title']
  .split(/\n/)
  .map(title => title.trim().toLowerCase())
  .filter(title => title.length > 0 && !title.includes(':') && !title.includes('management level'));

// Parse departments (newline separated) and break down into keywords
const departments = formData['Target Departments and Job Function']
  .split(/\n/)
  .map(dept => dept.trim())
  .filter(dept => dept.length > 0);

// Store original departments for person_departments field
const personDepartments = [...departments];

// Break down departments into individual keywords for person_titles
const departmentKeywords = [];
departments.forEach(dept => {
  const deptLower = dept.toLowerCase();
  departmentKeywords.push(deptLower);

  // Also add individual words from multi-word departments
  const words = deptLower.split(/\s+and\s+|\s+/);
  words.forEach(word => {
    if (word.length > 2 && !['and', 'the'].includes(word)) {
      departmentKeywords.push(word);
    }
  });
});

// COMBINE job titles + departments into person_titles array
const personTitles = [
  ...jobTitles,
  ...departmentKeywords
].filter((value, index, self) => self.indexOf(value) === index); // Remove duplicates

// ===== OUTPUT =====

return {
  json: {
    // Company filters
    company_locations: companyLocations,
    company_employees: companyEmployees,
    company_keywords: companyKeywords,
    company_industries: companyIndustries,
    company_technologies: companyTechnologies,

    // Person filters
    person_titles: personTitles,
    person_departments: personDepartments,

    // Keep raw data for debugging/reference
    _raw: {
      locations: formData['Company Locations'],
      employees: formData['Employee Ranges'],
      keywords: formData['Company Keywords'],
      industries: formData['Industries'],
      technologies: formData['Technologies'],
      titles: formData['Job Title'],
      departments: formData['Target Departments and Job Function']
    }
  }
};

// ============================================
// EXTRACT ENRICHED COMPANY DATA - FIXED
// Now properly extracts technologies from Apollo response
// ============================================

const inputData = $input.all();

console.log('🔥 EXTRACTING ENRICHED COMPANY DATA...');
console.log(`📦 Total input items: ${inputData.length}`);

// Get original company data from "Extract Companies" node
const originalCompanies = $('Extract Companies').all();
console.log(`📋 Original companies count: ${originalCompanies.length}`);

// Apollo Company Enrich returns data in different formats
let enrichedOrganizations = [];

// Case 1: Single response with "organization" field (single company enrich)
if (inputData.length === 1 && inputData[0].json.organization) {
  enrichedOrganizations = [inputData[0].json.organization];
  console.log('✅ Format: Single organization object');
}
// Case 2: Single response with "organizations" array (batch enrich)
else if (inputData.length === 1 && inputData[0].json.organizations) {
  enrichedOrganizations = inputData[0].json.organizations;
  console.log(`✅ Format: Organizations array with ${enrichedOrganizations.length} companies`);
}
// Case 3: Multiple individual responses
else if (inputData.length > 1) {
  enrichedOrganizations = inputData.map(item => item.json.organization || item.json).filter(Boolean);
  console.log(`✅ Format: Multiple individual responses, ${enrichedOrganizations.length} companies`);
}
// Case 4: Direct organizations in input
else if (inputData.length === 1 && Array.isArray(inputData[0].json)) {
